#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
using namespace std;

int N;
vector<long long> val;
vector<int> cPrimes;
int bestAns;

void dfs(int i, int cur, bool needExtraRoot)
{
    if (i == N)
    {
        bestAns = min(bestAns, cur + N + static_cast<int>(needExtraRoot));
        return;
    }

    if (i == 0)
        dfs(i + 1, cur, false);

    if (i == 0)
        dfs(i + 1, cur + cPrimes[i], true);
    else if (needExtraRoot)
        dfs(i + 1, cur + cPrimes[i], true);

    for (int j = 0; j < i; ++j)
    {
        if (val[i] != 0 && val[j] % val[i] == 0)
        {
            val[j] /= val[i];
            dfs(i + 1, cur, needExtraRoot);
            val[j] *= val[i];
        }
    }
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    val.resize(N);
    cPrimes.assign(N, 0);

    for (long long& x : val)
        cin >> x;

    sort(val.begin(), val.end(), greater<long long>());

    for (int i = 0; i < N; ++i)
    {
        long long temp = val[i];
        long long x = temp;

        for (long long j = 2; j <= x / j; ++j)
        {
            while (x % j == 0)
            {
                x /= j;
                ++cPrimes[i];
            }
        }

        if (x > 1)
            ++cPrimes[i];

        val[i] = temp;
    }

    bestAns = numeric_limits<int>::max();
    dfs(0, 0, false);

    cout << bestAns << '\n';
    return 0;
}

